  gFam: { ua: { orange: "Помаранчеве", red: "Червоне", blonde: "Блонд", pink: "Рожеве", cool: "Бірюзове / зелене", purple: "Бузкове" }, en: { orange: "Orange", red: "Red", blonde: "Blonde", pink: "Pink", cool: "Teal / green", purple: "Lilac" } }
